import crypto from 'node:crypto';
import { z } from 'zod';

/* === PHAN 1: SQL ROLE CO LAP (Chay trong Migration PostgreSQL) ===
CREATE ROLE dom_agent_advisory NOINHERIT LOGIN PASSWORD '...' NOSUPERUSER NOBYPASSRLS;
ALTER ROLE dom_agent_advisory SET default_transaction_read_only = on;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM dom_agent_advisory;
GRANT SELECT (id, project_name, unit_code, public_price, availability_status) ON crm_units TO dom_agent_advisory;
-- Advisory Agent khong bao gio co quyen INSERT/UPDATE/DELETE hay doc cot phone_raw
*/

// === PHAN 2: SCOPED EPHEMERAL TOKEN BROKER CHO WRITE WORKER ===
const WriteCapabilitySchema = z.object({
  tenantId: z.string().uuid(),
  actorUserId: z.string().uuid(),
  allowedAction: z.enum(['crm.lead.append_note', 'crm.booking.create_draft']),
  targetRecordId: z.string().uuid(),
  maxMutations: z.literal(1),
});

// Tuyet doi cam LLM truyen tham so nhay cam qua Proposal Payload
const SafeDraftNotePayloadSchema = z.object({
  leadId: z.string().uuid(),
  summaryNote: z.string().min(5).max(500),
}).strict(); // .strict() chan moi truong la nhu status, ownerId, discountPct

export function mintEphemeralWriteToken(
  grantInput: z.infer<typeof WriteCapabilitySchema>,
  brokerSecret: string
): string {
  const grant = WriteCapabilitySchema.parse(grantInput);
  const nowSec = Math.floor(Date.now() / 1000);
  const claims = {
    ...grant,
    aud: 'domation-write-worker-v1', // Audience Binding kieu RFC 8707
    jti: crypto.randomUUID(),          // Single-use token ID
    iat: nowSec,
    exp: nowSec + 60,                  // Tu huy sau dung 60 giay
  };
  const bodyB64 = Buffer.from(JSON.stringify(claims)).toString('base64url');
  const sig = crypto.createHmac('sha256', brokerSecret).update(bodyB64).digest('base64url');
  return `${bodyB64}.${sig}`;
}

export async function executeScopedWriteWorker(
  token: string,
  rawPayload: unknown,
  brokerSecret: string,
  consumedJtiCache: Set<string>
) {
  const [bodyB64, sig] = token.split('.');
  if (!bodyB64 || !sig) throw new Error('DENY: Dinh dang Ephemeral Token khong hop le.');

  const expectedSig = crypto.createHmac('sha256', brokerSecret).update(bodyB64).digest('base64url');
  if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expectedSig))) {
    throw new Error('DENY: Chu ky Token Broker sai lech.');
  }

  const claims = JSON.parse(Buffer.from(bodyB64, 'base64url').toString('utf8'));
  if (claims.aud !== 'domation-write-worker-v1') throw new Error('DENY: Sai Audience.');
  if (Math.floor(Date.now() / 1000) > claims.exp) throw new Error('DENY: Token da het han 60s.');
  if (consumedJtiCache.has(claims.jti)) throw new Error('DENY: Token chi duoc dung 1 lan.');

  const safePayload = SafeDraftNotePayloadSchema.parse(rawPayload);
  if (safePayload.leadId !== claims.targetRecordId) {
    throw new Error('DENY: Vi pham pham vi targetRecordId (ngan sua cheo ban ghi).');
  }

  consumedJtiCache.add(claims.jti);
  return { ok: true, tenantId: claims.tenantId, mutatedRecord: safePayload.leadId };
}
